import json
import sqlite3
from collections import defaultdict

from pymilvus import connections, Collection
from pymilvus.orm.types import DataType

# 1) 固定配置(按题目要求原样使用)
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_cfg = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530',
}

neo4j_cfg = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def safe_connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def detect_vector_field(collection: Collection) -> str:
    # 自动找FLOAT_VECTOR字段名，避免你schema里字段名不同导致代码不可运行
    for f in collection.schema.fields:
        if f.dtype == DataType.FLOAT_VECTOR:
            return f.name
    raise RuntimeError("No FLOAT_VECTOR field found in Milvus collection schema.")


def detect_id_field(collection: Collection) -> str:
    # 优先用primary key；否则尝试常见字段名
    for f in collection.schema.fields:
        if getattr(f, 'is_primary', False):
            return f.name
    for guess in ["photo_id", "id", "pk"]:
        if any(ff.name == guess for ff in collection.schema.fields):
            return guess
    # 退化：Milvus hit.id 也可能直接就是主键
    return "__HIT_ID__"


def embed_text_for_clip(text: str):
    """用CLIP文本编码生成向量。

    注意：你的photo_vector如果是CLIP/多模态嵌入，这样才能实现“文本搜图”。
    若你当初用的不是CLIP，而是别的embedding方式，需要替换模型。
    """
    try:
        from sentence_transformers import SentenceTransformer
    except ImportError as e:
        raise ImportError(
            "Missing dependency: sentence-transformers. Install with: pip install sentence-transformers"
        ) from e

    # 常见可用的CLIP模型（若你生成photo向量时用的不同模型，请改成同一个）
    model = SentenceTransformer("sentence-transformers/clip-ViT-B-32")
    vec = model.encode([text], normalize_embeddings=True)
    return vec[0].tolist()


def chunked(seq, n):
    for i in range(0, len(seq), n):
        yield seq[i:i+n]


def main():
    city = "Indianapolis"
    category_keyword = "Burgers"
    image_query = "a photo of burgers and fries"

    # --- SQLite connections ---
    conn_biz = safe_connect_sqlite(sqlite_paths["business"])
    conn_photo = safe_connect_sqlite(sqlite_paths["photo"])
    conn_review = safe_connect_sqlite(sqlite_paths["review"])
    conn_user = safe_connect_sqlite(sqlite_paths["user"])

    # --- Step 1: candidate businesses (Indianapolis + Burgers) ---
    # 表名假设为 business；若你实际表名不同，请自行改
    biz_sql = (
        "SELECT business_id, name, address, city, state, postal_code, categories "
        "FROM business "
        "WHERE city = ? AND categories LIKE ?"
    )
    biz_rows = conn_biz.execute(biz_sql, (city, f"%{category_keyword}%")).fetchall()
    biz_candidates = [dict(r) for r in biz_rows]
    biz_ids = [b["business_id"] for b in biz_candidates]

    if not biz_candidates:
        print(json.dumps({"results": [], "note": "No Burgers businesses found in Indianapolis."}, ensure_ascii=False, indent=2))
        return

    # --- Step 2: Milvus search photos for burgers+fries ---
    connections.connect(alias="default", host=milvus_cfg["milvus_host"], port=milvus_cfg["milvus_port"])
    photo_col_name = milvus_cfg['milvus_collections']['photos']
    photo_col = Collection(photo_col_name)
    photo_col.load()

    vector_field = detect_vector_field(photo_col)
    id_field = detect_id_field(photo_col)

    query_vec = embed_text_for_clip(image_query)

    search_params = {"metric_type": "IP", "params": {"nprobe": 16}}

    # 尽量取到photo_id；若schema没有该output field也不致命
    output_fields = []
    if id_field not in ["__HIT_ID__"]:
        output_fields.append(id_field)
    # 常见情况：除了主键，还会单独存一个photo_id字段
    if any(f.name == "photo_id" for f in photo_col.schema.fields) and "photo_id" not in output_fields:
        output_fields.append("photo_id")

    hits = photo_col.search(
        data=[query_vec],
        anns_field=vector_field,
        param=search_params,
        limit=200,
        output_fields=output_fields,
    )

    # 提取photo_ids
    photo_ids = []
    for h in hits[0]:
        # 1) 如果output_fields含photo_id
        pid = None
        try:
            if hasattr(h, "entity") and h.entity is not None:
                if "photo_id" in getattr(h.entity, "fields", {}) or "photo_id" in (output_fields or []):
                    try:
                        pid = h.entity.get("photo_id")
                    except Exception:
                        pid = None
                if pid is None and id_field != "__HIT_ID__":
                    try:
                        pid = h.entity.get(id_field)
                    except Exception:
                        pid = None
        except Exception:
            pid = None

        # 2) 退化：用h.id
        if pid is None:
            try:
                pid = h.id
            except Exception:
                pid = None

        if pid is not None:
            photo_ids.append(str(pid))

    if not photo_ids:
        print(json.dumps({
            "results": [],
            "note": "Milvus returned no photo hits for query 'burgers and fries'. Check your embedding model matches the one used to build photo_vector."
        }, ensure_ascii=False, indent=2))
        return

    # --- Step 3: join photos back to SQLite photo table; filter by candidate businesses ---
    # 表名假设为 photo，字段假设含 photo_id, business_id, label, caption
    matched_photos = []
    biz_id_set = set(biz_ids)

    # IN参数分块，避免SQLite变量过多
    for block in chunked(photo_ids, 800):
        placeholders = ",".join(["?"] * len(block))
        photo_sql = (
            f"SELECT photo_id, business_id, label, caption "
            f"FROM photo "
            f"WHERE photo_id IN ({placeholders})"
        )
        rows = conn_photo.execute(photo_sql, block).fetchall()
        for r in rows:
            d = dict(r)
            if d.get("business_id") in biz_id_set:
                matched_photos.append(d)

    if not matched_photos:
        print(json.dumps({
            "results": [],
            "note": "Found Milvus burger+fries photo hits, but none belong to Indianapolis Burgers businesses (after joining via photo.db)."
        }, ensure_ascii=False, indent=2))
        return

    matched_biz_ids = sorted({p["business_id"] for p in matched_photos if p.get("business_id")})

    # --- Step 4: reviews mentioning big portions + user names ---
    portion_patterns = [
        "%big portion%",
        "%big portions%",
        "%large portion%",
        "%large portions%",
        "%huge portion%",
        "%huge portions%",
        "%generous portion%",
        "%generous portions%",
        "%massive portion%",
        "%massive portions%",
        "%portion size%",
        "%portions are%",
    ]

    reviews_by_biz = defaultdict(list)
    user_ids_needed = set()

    # 分块查询business_id
    for biz_block in chunked(matched_biz_ids, 200):
        biz_ph = ",".join(["?"] * len(biz_block))
        like_clause = " OR ".join(["text LIKE ?" for _ in portion_patterns])
        review_sql = (
            f"SELECT review_id, business_id, user_id, text, date, stars "
            f"FROM review "
            f"WHERE business_id IN ({biz_ph}) AND ({like_clause})"
        )
        params = list(biz_block) + portion_patterns
        rws = conn_review.execute(review_sql, params).fetchall()
        for r in rws:
            d = dict(r)
            reviews_by_biz[d["business_id"]].append(d)
            if d.get("user_id"):
                user_ids_needed.add(d["user_id"])

    # 查用户名
    user_name = {}
    user_ids_needed = list(user_ids_needed)
    for ublock in chunked(user_ids_needed, 800):
        ph = ",".join(["?"] * len(ublock))
        user_sql = f"SELECT user_id, name FROM user WHERE user_id IN ({ph})"
        for r in conn_user.execute(user_sql, ublock).fetchall():
            user_name[r["user_id"]] = r["name"]

    # --- Step 5: aggregate output ---
    biz_map = {b["business_id"]: b for b in biz_candidates}
    photos_by_biz = defaultdict(list)
    for p in matched_photos:
        photos_by_biz[p["business_id"]].append({
            "photo_id": p.get("photo_id"),
            "label": p.get("label"),
            "caption": p.get("caption"),
        })

    results = []
    for bid in matched_biz_ids:
        b = biz_map.get(bid)
        if not b:
            continue
        address = ", ".join([x for x in [b.get("address"), b.get("city"), b.get("state"), b.get("postal_code")] if x])

        # 控制每家店照片输出数量（可调整）
        photos = photos_by_biz.get(bid, [])[:5]

        revs = []
        for r in reviews_by_biz.get(bid, [])[:10]:
            txt = (r.get("text") or "")
            snippet = txt[:240].replace("\n", " ") + ("..." if len(txt) > 240 else "")
            revs.append({
                "review_id": r.get("review_id"),
                "user_id": r.get("user_id"),
                "user_name": user_name.get(r.get("user_id")),
                "stars": r.get("stars"),
                "date": r.get("date"),
                "snippet": snippet
            })

        results.append({
            "business_id": bid,
            "name": b.get("name"),
            "address": address,
            "categories": b.get("categories"),
            "photos_burger_and_fries": photos,
            "reviewers_mentioning_big_portions": revs
        })

    # 只保留同时满足：有匹配照片 + 有分量大评论（如果你想“只要其一”可改这里）
    results = [r for r in results if r["photos_burger_and_fries"] and r["reviewers_mentioning_big_portions"]]

    print(json.dumps({"results": results, "counts": {"businesses": len(results)}}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        print(json.dumps({"error": str(e)}, ensure_ascii=False, indent=2))
